11	struct BrowserSplitView: View {
12	    @Environment(BrowserModel.self) private var browserModel
13	    @Environment(AppPreferences.self) private var appPreferences
14	
15	    var body: some View {
16	        @Bindable var browserModel = browserModel
17	
18	        ZStack(alignment: .top) {
19	            if let pageSession = browserModel.activePageSession {
20	                BrowserDetailView(pageSession: pageSession)
21	            } else {
22	                BlankTabView()
23	            }
24	
25	            if browserModel.isFindBarVisible {
26	                VStack {
27	                    HStack {
28	                        Spacer()
29	
30	                        FindBar(
31	                            text: $browserModel.findText,
32	                            focusRequestID: browserModel.findFocusRequestID,
33	                            onTextChange: { browserModel.updateFindText($0) },
34	                            onPrevious: { browserModel.findPreviousInPage() },
35	                            onNext: { browserModel.findNextInPage() },
36	                            onClose: { browserModel.closeFindInPage() }
37	                        )
38	                        .padding(.trailing, 18)
39	                    }
40	                    .padding(.top, appPreferences.tabLayout == .separate ? 130 : 84)
41	
42	                    Spacer()
43	                }
44	                .transition(.move(edge: .top).combined(with: .opacity))
45	            }
46	
47	            SafariLiquidChrome(tabLayout: appPreferences.tabLayout)
48	        }
49	        .ignoresSafeArea(.container, edges: [.top, .bottom])
50	        .animation(.smooth(duration: 0.16), value: browserModel.isFindBarVisible)
51	        .containerBackground(.clear, for: .window)
52	        .background(SafariWindowChromeConfigurator())
53	        .toolbar(removing: .title)
54	        .sheet(isPresented: $browserModel.isHistoryVisible) {
55	            HistoryView(historyStore: browserModel.historyStore) { entry in
56	                browserModel.openHistoryEntry(entry)
57	            }
58	            .frame(minWidth: 640, minHeight: 520)
59	        }
60	    }
61	}
