63	private struct SafariLiquidChrome: View {
64	    @Environment(BrowserModel.self) private var browserModel
65	    let tabLayout: BrowserTabLayout
66	
67	    var body: some View {
68	        ZStack(alignment: .top) {
69	            SafariChromeBacking(tabLayout: tabLayout)
70	
71	            GlassEffectContainer(spacing: 14) {
72	                VStack(spacing: 0) {
73	                    HStack(spacing: 14) {
74	                        Color.clear
75	                            .frame(width: 122)
76	
77	                        SidebarHistoryPill()
78	
79	                        NavigationControls()
80	
81	                        Spacer(minLength: 24)
82	
83	                        if tabLayout == .compact {
84	                            CompactTabStrip()
85	                                .frame(minWidth: 420, idealWidth: 680, maxWidth: 860)
86	                        } else {
87	                            AddressField()
88	                                .frame(minWidth: 420, idealWidth: 640, maxWidth: 780)
89	                        }
90	
91	                        Spacer(minLength: 24)
92	
93	                        ToolbarActionPill()
94	
95	                        PrivateWindowIndicator()
96	                    }
97	                    .padding(.leading, 16)
98	                    .padding(.trailing, 18)
99	                    .frame(height: SafariChromeMetrics.topBarHeight)
100	
101	                    if tabLayout == .separate {
102	                        SeparateTabBar()
103	                    }
104	                }
105	            }
106	        }
107	        .frame(height: SafariChromeMetrics.height(for: tabLayout), alignment: .top)
108	    }
109	}
