111	private enum SafariChromeMetrics {
112	    static let topBarHeight: CGFloat = 74
113	    static let separateTabBarHeight: CGFloat = 48
114	
115	    static func height(for tabLayout: BrowserTabLayout) -> CGFloat {
116	        tabLayout == .separate ? topBarHeight + separateTabBarHeight : topBarHeight
117	    }
118	}
119	
120	private let chromeBaseColor = Color(red: 0.10, green: 0.12, blue: 0.18)
121	private let chromeShelfColor = Color(red: 0.14, green: 0.16, blue: 0.24)
122	private struct SafariChromeBacking: View {
123	    @Environment(\.colorScheme) private var colorScheme
124	    let tabLayout: BrowserTabLayout
125	
126	    private var topOpacity: Double {
127	        colorScheme == .dark ? 0.95 : 0.82
128	    }
129	
130	    private var shelfOpacity: Double {
131	        colorScheme == .dark ? 0.92 : 0.76
132	    }
133	
134	    var body: some View {
135	        VStack(spacing: 0) {
136	            Rectangle()
137	                .fill(chromeBaseColor.opacity(topOpacity))
138	                .frame(height: SafariChromeMetrics.topBarHeight)
139	                .overlay(alignment: .bottom) {
140	                    Rectangle()
141	                        .fill(Color.white.opacity(colorScheme == .dark ? 0.08 : 0.20))
142	                        .frame(height: 1)
143	                }
144	
145	            if tabLayout == .separate {
146	                Rectangle()
147	                    .fill(chromeShelfColor.opacity(shelfOpacity))
148	                    .frame(height: SafariChromeMetrics.separateTabBarHeight)
149	                    .overlay(alignment: .bottom) {
150	                        Rectangle()
151	                            .fill(Color.black.opacity(colorScheme == .dark ? 0.32 : 0.14))
152	                            .frame(height: 1)
153	                    }
154	            }
155	        }
156	        .ignoresSafeArea(edges: .top)
157	    }
158	}
