160	private struct SafariWindowChromeConfigurator: NSViewRepresentable {
161	    func makeNSView(context: Context) -> NSView {
162	        let view = NSView()
163	        DispatchQueue.main.async {
164	            configure(window: view.window)
165	        }
166	        return view
167	    }
168	
169	    func updateNSView(_ nsView: NSView, context: Context) {
170	        DispatchQueue.main.async {
171	            configure(window: nsView.window)
172	        }
173	    }
174	
175	    private func configure(window: NSWindow?) {
176	        guard let window else {
177	            return
178	        }
179	
180	        window.titleVisibility = .hidden
181	        window.titlebarAppearsTransparent = true
182	        window.styleMask.insert(.fullSizeContentView)
183	        window.isMovableByWindowBackground = true
184	        window.isOpaque = false
185	        window.backgroundColor = .clear
186	    }
187	}
