242	private struct GlassPill<Content: View>: View {
243	    let height: CGFloat
244	    let cornerRadius: CGFloat
245	    let content: Content
246	
247	    init(height: CGFloat, cornerRadius: CGFloat, @ViewBuilder content: () -> Content) {
248	        self.height = height
249	        self.cornerRadius = cornerRadius
250	        self.content = content()
251	    }
252	
253	    var body: some View {
254	        content
255	            .frame(height: height)
256	            .glassEffect(.regular, in: RoundedRectangle(cornerRadius: cornerRadius, style: .continuous))
257	    }
258	}
