260	private struct LiquidIconButton: View {
261	    let title: String
262	    let systemImage: String
263	    let action: () -> Void
264	
265	    @State private var isHovering = false
266	
267	    var body: some View {
268	        Button(action: action) {
269	            Image(systemName: systemImage)
270	                .font(.system(size: 19, weight: .medium))
271	                .frame(width: 38, height: 34)
272	                .contentShape(Rectangle())
273	        }
274	        .buttonStyle(.glass)
275	        .foregroundStyle(.white.opacity(isHovering ? 1 : 0.86))
276	        .help(title)
277	        .onHover { isHovering = $0 }
278	    }
279	}
