459	private struct CloseTabButton: View {
460	    enum Prominence {
461	        case selected
462	        case inactive
463	    }
464	
465	    @Environment(BrowserModel.self) private var browserModel
466	    let tab: BrowserTab
467	    var prominence: Prominence = .inactive
468	
469	    @State private var isHovering = false
470	
471	    private var opacity: Double {
472	        if isHovering {
473	            return 1
474	        }
475	        switch prominence {
476	        case .selected:
477	            return 0.72
478	        case .inactive:
479	            return 0.42
480	        }
481	    }
482	
483	    var body: some View {
484	        Button("Close Tab", systemImage: "xmark") {
485	            browserModel.close(tab)
486	        }
487	        .labelStyle(.iconOnly)
488	        .font(.system(size: 10, weight: .semibold))
489	        .buttonStyle(.plain)
490	        .foregroundStyle(.white.opacity(0.84))
491	        .opacity(opacity)
492	        .frame(width: 18, height: 18)
493	        .background {
494	            Circle()
495	                .fill(isHovering ? Color.primary.opacity(0.08) : Color.clear)
496	        }
497	        .help("Close Tab")
498	        .onHover { isHovering = $0 }
