522	private enum AddressFieldRole {
523	    case toolbar
524	    case compactTab
525	}
526	
527	private struct AddressField: View {
528	    @Environment(BrowserModel.self) private var browserModel
529	    var role: AddressFieldRole = .toolbar
530	    @FocusState private var isFocused: Bool
531	
532	    var body: some View {
533	        @Bindable var browserModel = browserModel
534	        let pageSession = browserModel.activePageSession
535	        let isPageLoading = pageSession?.isLoading == true
536	
537	        GlassPill(height: role == .toolbar ? 48 : 36, cornerRadius: role == .toolbar ? 24 : 18) {
538	            HStack(spacing: 8) {
539	                Image(systemName: "magnifyingglass")
540	                    .font(.system(size: 17, weight: .medium))
541	                    .foregroundStyle(.white.opacity(0.72))
542	
543	                TextField("Search or enter website name", text: $browserModel.addressText)
544	                    .textFieldStyle(.plain)
545	                    .font(.system(size: role == .toolbar ? 18 : 14, weight: .medium))
546	                    .foregroundStyle(.white)
547	                    .focused($isFocused)
548	                    .onSubmit {
549	                        browserModel.submitAddressBar()
550	                    }
551	
552	                Button {
553	                    if isPageLoading {
554	                        pageSession?.stopLoading()
555	                    } else {
556	                        pageSession?.reload()
557	                    }
558	                } label: {
559	                    Image(systemName: isPageLoading ? "xmark" : "arrow.clockwise")
560	                        .font(.system(size: 13, weight: .semibold))
561	                        .frame(width: 16, height: 16)
562	                }
563	                .buttonStyle(.plain)
564	                .foregroundStyle(.white.opacity(pageSession == nil ? 0.36 : 0.72))
565	                .disabled(pageSession == nil)
566	                .accessibilityLabel(isPageLoading ? "Stop" : "Reload")
567	                .help(isPageLoading ? "Stop" : "Reload")
568	            }
569	            .padding(.leading, role == .toolbar ? 16 : 12)
570	            .padding(.trailing, role == .toolbar ? 12 : 10)
571	        }
