755	private struct MountainBand: View {
756	    let y: CGFloat
757	    let color: Color
758	    let points: [CGFloat]
759	
760	    var body: some View {
761	        GeometryReader { proxy in
762	            Path { path in
763	                let width = proxy.size.width
764	                let height = proxy.size.height
765	                let baseY = height * y
766	                let step = width / CGFloat(max(points.count - 1, 1))
767	
768	                path.move(to: CGPoint(x: 0, y: baseY + height * points[0]))
769	
770	                for index in 1..<points.count {
771	                    let previousX = CGFloat(index - 1) * step
772	                    let x = CGFloat(index) * step
773	                    let previousY = baseY + height * points[index - 1]
774	                    let nextY = baseY + height * points[index]
775	                    path.addCurve(
776	                        to: CGPoint(x: x, y: nextY),
777	                        control1: CGPoint(x: previousX + step * 0.38, y: previousY),
778	                        control2: CGPoint(x: x - step * 0.38, y: nextY)
779	                    )
780	                }
781	
782	                path.addLine(to: CGPoint(x: width, y: height))
783	                path.addLine(to: CGPoint(x: 0, y: height))
784	                path.closeSubpath()
785	            }
786	            .fill(color)
787	        }
788	        .ignoresSafeArea()
789	    }
790	}
