/*
See the LICENSE.txt file for this sample's licensing information.

Abstract:
Safari-style browser shell with top chrome and hibernated tabs.
*/

import AppKit
import SwiftUI

struct BrowserSplitView: View {
    @Environment(BrowserModel.self) private var browserModel
    @Environment(AppPreferences.self) private var appPreferences

    var body: some View {
        @Bindable var browserModel = browserModel

        ZStack(alignment: .top) {
            if let pageSession = browserModel.activePageSession {
                BrowserDetailView(pageSession: pageSession)
            } else {
                BlankTabView()
            }

            if browserModel.isFindBarVisible {
                VStack {
                    HStack {
                        Spacer()

                        FindBar(
                            text: $browserModel.findText,
                            focusRequestID: browserModel.findFocusRequestID,
                            onTextChange: { browserModel.updateFindText($0) },
                            onPrevious: { browserModel.findPreviousInPage() },
                            onNext: { browserModel.findNextInPage() },
                            onClose: { browserModel.closeFindInPage() }
                        )
                        .padding(.trailing, 18)
                    }
                    .padding(.top, appPreferences.tabLayout == .separate ? 130 : 84)

                    Spacer()
                }
                .transition(.move(edge: .top).combined(with: .opacity))
            }

            SafariLiquidChrome(tabLayout: appPreferences.tabLayout)
        }
        .ignoresSafeArea(.container, edges: [.top, .bottom])
        .animation(.smooth(duration: 0.16), value: browserModel.isFindBarVisible)
        .containerBackground(.clear, for: .window)
        .background(SafariWindowChromeConfigurator())
        .toolbar(removing: .title)
        .sheet(isPresented: $browserModel.isHistoryVisible) {
            HistoryView(historyStore: browserModel.historyStore) { entry in
                browserModel.openHistoryEntry(entry)
            }
            .frame(minWidth: 640, minHeight: 520)
        }
    }
}

private struct SafariLiquidChrome: View {
    @Environment(BrowserModel.self) private var browserModel
    let tabLayout: BrowserTabLayout

    var body: some View {
        ZStack(alignment: .top) {
            SafariChromeBacking(tabLayout: tabLayout)

            GlassEffectContainer(spacing: 14) {
                VStack(spacing: 0) {
                    HStack(spacing: 14) {
                        Color.clear
                            .frame(width: 122)

                        SidebarHistoryPill()

                        NavigationControls()

                        Spacer(minLength: 24)

                        if tabLayout == .compact {
                            CompactTabStrip()
                                .frame(minWidth: 420, idealWidth: 680, maxWidth: 860)
                        } else {
                            AddressField()
                                .frame(minWidth: 420, idealWidth: 640, maxWidth: 780)
                        }

                        Spacer(minLength: 24)

                        ToolbarActionPill()

                        PrivateWindowIndicator()
                    }
                    .padding(.leading, 16)
                    .padding(.trailing, 18)
                    .frame(height: SafariChromeMetrics.topBarHeight)

                    if tabLayout == .separate {
                        SeparateTabBar()
                    }
                }
            }
        }
        .frame(height: SafariChromeMetrics.height(for: tabLayout), alignment: .top)
    }
}

private enum SafariChromeMetrics {
    static let topBarHeight: CGFloat = 74
    static let separateTabBarHeight: CGFloat = 48

    static func height(for tabLayout: BrowserTabLayout) -> CGFloat {
        tabLayout == .separate ? topBarHeight + separateTabBarHeight : topBarHeight
    }
}

private let chromeBaseColor = Color(red: 0.10, green: 0.12, blue: 0.18)
private let chromeShelfColor = Color(red: 0.14, green: 0.16, blue: 0.24)
private struct SafariChromeBacking: View {
    @Environment(\.colorScheme) private var colorScheme
    let tabLayout: BrowserTabLayout

    private var topOpacity: Double {
        colorScheme == .dark ? 0.95 : 0.82
    }

    private var shelfOpacity: Double {
        colorScheme == .dark ? 0.92 : 0.76
    }

    var body: some View {
        VStack(spacing: 0) {
            Rectangle()
                .fill(chromeBaseColor.opacity(topOpacity))
                .frame(height: SafariChromeMetrics.topBarHeight)
                .overlay(alignment: .bottom) {
                    Rectangle()
                        .fill(Color.white.opacity(colorScheme == .dark ? 0.08 : 0.20))
                        .frame(height: 1)
                }

            if tabLayout == .separate {
                Rectangle()
                    .fill(chromeShelfColor.opacity(shelfOpacity))
                    .frame(height: SafariChromeMetrics.separateTabBarHeight)
                    .overlay(alignment: .bottom) {
                        Rectangle()
                            .fill(Color.black.opacity(colorScheme == .dark ? 0.32 : 0.14))
                            .frame(height: 1)
                    }
            }
        }
        .ignoresSafeArea(edges: .top)
    }
}

private struct SafariWindowChromeConfigurator: NSViewRepresentable {
    func makeNSView(context: Context) -> NSView {
        let view = NSView()
        DispatchQueue.main.async {
            configure(window: view.window)
        }
        return view
    }

    func updateNSView(_ nsView: NSView, context: Context) {
        DispatchQueue.main.async {
            configure(window: nsView.window)
        }
    }

    private func configure(window: NSWindow?) {
        guard let window else {
            return
        }

        window.titleVisibility = .hidden
        window.titlebarAppearsTransparent = true
        window.styleMask.insert(.fullSizeContentView)
        window.isMovableByWindowBackground = true
        window.isOpaque = false
        window.backgroundColor = .clear
    }
}

private struct SidebarHistoryPill: View {
    @Environment(BrowserModel.self) private var browserModel

    var body: some View {
        GlassPill(height: 44, cornerRadius: 22) {
            Menu {
                Button("Show History", systemImage: "clock.arrow.circlepath") {
                    browserModel.showHistory()
                }
                Button("Copy URL", systemImage: "doc.on.doc") {
                    browserModel.copyActivePageURL()
                }
            } label: {
                HStack(spacing: 12) {
                    Image(systemName: "sidebar.left")
                        .font(.system(size: 18, weight: .medium))

                    Image(systemName: "chevron.down")
                        .font(.system(size: 11, weight: .bold))
                }
                .padding(.horizontal, 14)
                .foregroundStyle(.white.opacity(0.9))
            }
            .menuStyle(.borderlessButton)
            .menuIndicator(.hidden)
            .help("Sidebar and History")
        }
    }
}

private struct ToolbarActionPill: View {
    @Environment(BrowserModel.self) private var browserModel

    var body: some View {
        GlassPill(height: 44, cornerRadius: 22) {
            HStack(spacing: 0) {
                LiquidIconButton(title: "Copy URL", systemImage: "square.and.arrow.up") {
                    browserModel.copyActivePageURL()
                }

                LiquidIconButton(title: "New Tab", systemImage: "plus") {
                    browserModel.createTab()
                }

                LiquidIconButton(title: "Show History", systemImage: "square.on.square") {
                    browserModel.showHistory()
                }
            }
            .padding(.horizontal, 7)
        }
    }
}

private struct GlassPill<Content: View>: View {
    let height: CGFloat
    let cornerRadius: CGFloat
    let content: Content

    init(height: CGFloat, cornerRadius: CGFloat, @ViewBuilder content: () -> Content) {
        self.height = height
        self.cornerRadius = cornerRadius
        self.content = content()
    }

    var body: some View {
        content
            .frame(height: height)
            .glassEffect(.regular, in: RoundedRectangle(cornerRadius: cornerRadius, style: .continuous))
    }
}

private struct LiquidIconButton: View {
    let title: String
    let systemImage: String
    let action: () -> Void

    @State private var isHovering = false

    var body: some View {
        Button(action: action) {
            Image(systemName: systemImage)
                .font(.system(size: 19, weight: .medium))
                .frame(width: 38, height: 34)
                .contentShape(Rectangle())
        }
        .buttonStyle(.glass)
        .foregroundStyle(.white.opacity(isHovering ? 1 : 0.86))
        .help(title)
        .onHover { isHovering = $0 }
    }
}

private struct SeparateTabBar: View {
    var body: some View {
        TabStrip()
            .padding(.horizontal, 18)
            .frame(height: SafariChromeMetrics.separateTabBarHeight)
    }
}

private struct NavigationControls: View {
    @Environment(BrowserModel.self) private var browserModel

    var body: some View {
        let pageSession = browserModel.activePageSession

        GlassPill(height: 44, cornerRadius: 22) {
            HStack(spacing: 0) {
                LiquidIconButton(title: "Back", systemImage: "chevron.backward") {
                    pageSession?.goBack()
                }
                .disabled(pageSession?.canGoBack != true)
                .opacity(pageSession?.canGoBack == true ? 1 : 0.45)

                Rectangle()
                    .fill(Color.white.opacity(0.16))
                    .frame(width: 1, height: 24)

