private struct MountainBand: View {
    let y: CGFloat
    let color: Color
    let points: [CGFloat]

    var body: some View {
        GeometryReader { proxy in
            Path { path in
                let width = proxy.size.width
                let height = proxy.size.height
                let baseY = height * y
                let step = width / CGFloat(max(points.count - 1, 1))

                path.move(to: CGPoint(x: 0, y: baseY + height * points[0]))

                for index in 1..<points.count {
                    let previousX = CGFloat(index - 1) * step
                    let x = CGFloat(index) * step
                    let previousY = baseY + height * points[index - 1]
                    let nextY = baseY + height * points[index]
                    path.addCurve(
                        to: CGPoint(x: x, y: nextY),
                        control1: CGPoint(x: previousX + step * 0.38, y: previousY),
                        control2: CGPoint(x: x - step * 0.38, y: nextY)
                    )
                }

                path.addLine(to: CGPoint(x: width, y: height))
                path.addLine(to: CGPoint(x: 0, y: height))
                path.closeSubpath()
            }
            .fill(color)
        }
        .ignoresSafeArea()
    }
}

