import SwiftUI

struct HistoryView: View {
    @Bindable var historyStore: HistoryStore
    let openEntry: (HistoryEntry) -> Void

    @State private var searchText = ""
    @State private var isClearConfirmationPresented = false

    private var filteredEntries: [HistoryEntry] {
        let query = searchText.trimmingCharacters(in: .whitespacesAndNewlines)
        guard query.isEmpty == false else {
            return historyStore.entries
        }

        return historyStore.entries.filter { entry in
            entry.title.localizedCaseInsensitiveContains(query)
                || entry.urlString.localizedCaseInsensitiveContains(query)
                || host(for: entry).localizedCaseInsensitiveContains(query)
        }
    }

    var body: some View {
        NavigationStack {
            VStack(spacing: 0) {
                HStack(spacing: 8) {
                    Image(systemName: "magnifyingglass")
                        .foregroundStyle(.secondary)

                    TextField("Search History", text: $searchText)
                        .textFieldStyle(.plain)
                }
                .padding(.horizontal, 12)
                .padding(.vertical, 8)
                .background(.quaternary, in: RoundedRectangle(cornerRadius: 8, style: .continuous))
                .padding([.horizontal, .top], 16)
                .padding(.bottom, 8)

                if filteredEntries.isEmpty {
                    ContentUnavailableView("No History", systemImage: "clock.arrow.circlepath")
                        .frame(maxWidth: .infinity, maxHeight: .infinity)
                } else {
                    List(filteredEntries) { entry in
                        HistoryEntryRow(entry: entry, host: host(for: entry)) {
                            openEntry(entry)
                        }
                    }
                    .listStyle(.inset)
                }
            }
            .navigationTitle("History")
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button("Clear History", systemImage: "trash") {
                        isClearConfirmationPresented = true
                    }
                    .disabled(historyStore.entries.isEmpty)
                }
            }
            .confirmationDialog(
                "Clear all browsing history?",
                isPresented: $isClearConfirmationPresented
            ) {
                Button("Clear History", role: .destructive) {
                    historyStore.clear()
                }
                Button("Cancel", role: .cancel) {
                }
            }
        }
    }

    private func host(for entry: HistoryEntry) -> String {
        URLComponents(string: entry.urlString)?.host ?? entry.urlString
    }
}

private struct HistoryEntryRow: View {
    let entry: HistoryEntry
    let host: String
    let openEntry: () -> Void

    var body: some View {
        HStack(spacing: 12) {
            VStack(alignment: .leading, spacing: 3) {
                Text(entry.title)
                    .font(.headline)
                    .lineLimit(1)

                Text(host)
                    .font(.subheadline)
                    .foregroundStyle(.secondary)
                    .lineLimit(1)

                Text(entry.urlString)
                    .font(.caption)
                    .foregroundStyle(.tertiary)
                    .lineLimit(1)
            }

            Spacer(minLength: 16)

            Text(entry.visitedAt, format: .dateTime.month().day().hour().minute())
                .font(.caption)
                .foregroundStyle(.secondary)
                .monospacedDigit()

            Button("Open", systemImage: "arrow.up.forward.square") {
                openEntry()
            }
            .labelStyle(.iconOnly)
            .buttonStyle(.borderless)
            .help("Open")
        }
        .padding(.vertical, 4)
    }
}

#Preview {
